# Deploy only reviewed owned UROP source; no dataset/model execution here.
from pathlib import Path
import base64,hashlib,io,json,zipfile,sys
payload=base64.b64decode('')
assert hashlib.sha256(payload).hexdigest()=='e9efc3742d3a3e618f1689e922da991c94bb91c2428fc6f537c9c0330a4c1b96'
deployment=Path('/content/urop_api_transport_source_e9efc3742d3a3e61')
manifest={'collab/drive_api_storage_v1.py': 'd7603e6bad1af1560a9422caccf7846de0ca73e37b4d10cbb6249744c2568be4', 'collab/pack_usable_images_api_v1.py': '9adbb9f1b00aaeaed5fc35de8dc23b3574f20b9a0af601b25b51737bcf5a2e54', 'scripts/usable_cohort_v2.py': '22bff1eb0fa14d102ad07786f936c5c1ed1582ec7bd5cee2b8e8dc5eb3520092'}
with zipfile.ZipFile(io.BytesIO(payload)) as archive:
 assert set(archive.namelist())==set(manifest)
 for name,digest in manifest.items():
  content=archive.read(name);assert hashlib.sha256(content).hexdigest()==digest
  path=deployment/name;assert path.resolve().is_relative_to(deployment.resolve())
  path.parent.mkdir(parents=True,exist_ok=True)
  if path.exists():assert path.read_bytes()==content
  else:path.write_bytes(content)
sys.path.insert(0,str(deployment/'collab'));sys.path.insert(0,str(deployment/'scripts'))
print(json.dumps({'state':'api_transport_owned_source_deployed','bundle_sha256':'e9efc3742d3a3e618f1689e922da991c94bb91c2428fc6f537c9c0330a4c1b96','files':len(manifest),'training':False}),flush=True)
